style.css:
:root{
    --miku-blue:#8EE9FF;
    --miku-purple:#B7A8FF;
    --miku-white:#F7FBFF;
    --background:#111827;
}

body{
    background: linear-gradient(180deg,#111827,#1B2336);
    color: var(--miku-white);
    font-family: "Segoe UI", sans-serif;
}

button{
    background: linear-gradient(45deg,var(--miku-blue),var(--miku-purple));
    color:white;
    border:none;
    border-radius:12px;
    transition:.3s;
}

button:hover{
    transform:scale(1.05);
    filter:brightness(1.1);
}

input, textarea{
    background:#1F2937;
    color:white;
    border:1px solid var(--miku-blue);
    border-radius:8px;
}

a{
    color:var(--miku-blue);
}
